i = 1;


/*

** Run do loop while i is

** less than or equal to 4

*/

do while i <= 4;

   // Initialize counter for internal do loop

   j = 1;


   /*

   ** Run internal do loop while j is

   ** less than or equal to 3

   */

   do while j <= 3;

      print space i comma j;;


      // Advance j

      j = j + 1;

   endo;


   // Advance i

   i = i + 1;


   // Print newline

   print;

endo;
